const projects={horizonte:{title:'Casa Horizonte',copy:'Uma casa organizada em torno da paisagem. O estudo explora aberturas amplas, circulação fluida e materiais naturais para aproximar interior e exterior.',facts:'Residencial · Área ilustrativa: 240 m² · Madeira, concreto e vidro'},refugio:{title:'Refúgio urbano',copy:'Um apartamento que desacelera o ritmo da cidade. Tons terrosos, luz suave e mobiliário de linhas simples estruturam um ambiente acolhedor.',facts:'Interiores · Área ilustrativa: 86 m² · Paleta terracota e madeira'},atelie:{title:'Ateliê de encontros',copy:'Um espaço comercial pensado para receber. A proposta combina áreas de exposição, uma mesa de conversa e circulação acessível.',facts:'Comercial · Área ilustrativa: 120 m² · Layout flexível'}};document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('[data-category]').forEach(p=>p.hidden=b.dataset.filter!=='all'&&p.dataset.category!==b.dataset.filter)}));document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>{const p=projects[b.dataset.project];document.getElementById('project-title').textContent=p.title;document.getElementById('project-copy').textContent=p.copy;document.getElementById('project-facts').textContent=p.facts;document.getElementById('project-dialog').showModal()}));

const covers=[['Casa Horizonte','../assets/architecture.svg','01 / Casa Horizonte'],['Refúgio urbano','../assets/interior.svg','02 / Refúgio urbano'],['Ateliê de encontros','../assets/interior.svg','03 / Ateliê de encontros']];let cover=0;function changeCover(delta){cover=(cover+delta+covers.length)%covers.length;const c=covers[cover];document.getElementById('cover-name').textContent=c[0];document.getElementById('cover-count').textContent=String(cover+1).padStart(2,'0')+' / 03';document.getElementById('cover-caption').textContent=c[2];const img=document.querySelector('.hero-image img');img.src=c[1];img.alt='Estudo conceitual: '+c[0]}document.getElementById('cover-prev').addEventListener('click',()=>changeCover(-1));document.getElementById('cover-next').addEventListener('click',()=>changeCover(1));
